/* Card set: Cryptids & Mythology (generated from the approved roster.csv by the Cryptids build).
   (cryptids.js exceeds the comfortable push size, so the remaining cards live in
   cryptids-additions.js, which must stay directly after 'cryptids.js' in sets/manifest.js.) */
CardSets.register({"id":"cryptids","name":"Cryptids & Mythology","code":"CRYP","description":"400 cards of the creatures people swear they saw — cryptids of North America and the world, Greek and Asian myth, Norse and Celtic legend, and the monsters of sea and sky.","theme":{"primary":"#2e5c3a","secondary":"#8cc896","artBackground":"#101a12","artFit":"cover"},"pack":{"name":"Cryptids & Mythology Pack","emblem":"🐉","skin":"cryptids"},"cards":[{"name":"Bigfoot","rarity":"chase","id":"bigfoot","subtitle":"Cryptid","details":"Reports from the Pacific Northwest describe a huge, hairy, ape-like figure; the 1967 Patterson-Gimlin film made Bluff Creek, California famous.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2016ShawneeBigfoot.jpg?width=1024"},{"name":"Loch Ness Monster","rarity":"chase","id":"loch-ness-monster","subtitle":"Cryptid","details":"Said to haunt Scotland's Loch Ness since 1933, when modern sightings described a long neck and humps breaking the dark surface.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Loch%20Ness%20Monster%20Surgeon%27s%20photograph.jpg?width=1024"},{"name":"Mothman","rarity":"chase","id":"mothman","subtitle":"Cryptid","details":"Point Pleasant, West Virginia reports in 1966 described a tall flying figure with glowing red eyes, seen near the Silver Bridge before it fell.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mothman%20Statue%202025.jpg?width=1024"},{"name":"Kraken","rarity":"chase","id":"kraken","subtitle":"Sea Monster","details":"Norwegian sailors' tales described a vast sea creature whose arms could drag whole ships beneath the waves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Le%20Poulpe%20Colossal.jpg?width=500"},{"name":"European Dragon","rarity":"chase","id":"european-dragon","subtitle":"Monster","details":"Medieval European tales told of winged, fire-breathing dragons hoarding gold, until knights and saints set out to slay them.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Saint%20George%20and%20the%20Dragon%20by%20Paolo%20Uccello%20%28London%29%2001.jpg?width=1024"},{"name":"Chupacabra","rarity":"chase","id":"chupacabra","subtitle":"Cryptid","details":"Reports began in Puerto Rico in 1995, describing a spined creature blamed for livestock drained of blood; sightings spread across the Southwest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chupacabras.JPG?width=1024"},{"name":"Yeti","rarity":"chase","id":"yeti","subtitle":"Cryptid","details":"Reports from Himalayan climbers and Sherpa traditions in Nepal describe a large, shaggy, ape-like figure crossing high snows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yeti%20coloris%C3%A9.jpg?width=1024"},{"name":"Jersey Devil","rarity":"chase","id":"jersey-devil","subtitle":"Cryptid","details":"Pine Barrens folklore tells of a winged, hoofed creature born to Mother Leeds in 1735; a wave of New Jersey sightings followed in 1909.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jersey%20Devil%20Philadelphia%20Post%201909.jpg?width=1024"},{"name":"Unicorn","rarity":"chase","id":"unicorn","subtitle":"Mythical Creature","details":"Medieval European legend held the unicorn a wild horned horse, tameable only by a maiden, its horn said to purify poisoned water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Unicorn%20in%20Captivity%20%28from%20the%20Unicorn%20Tapestries%29%20MET%20DP101252.jpg?width=800"},{"name":"Phoenix","rarity":"chase","id":"phoenix","subtitle":"Mythical Creature","details":"Greek writers told of a long-lived bird that burned at life's end and rose renewed from its own ashes, in a cycle without end.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Phoenix%20detail%20from%20Aberdeen%20Bestiary.jpg?width=1024"},{"name":"Thunderbird","rarity":"legendary","id":"thunderbird","subtitle":"Cryptid","details":"Native traditions across North America tell of an enormous bird whose wings are said to beat thunder; giant-bird reports persist to this day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thunderbird%20on%20Totem%20Pole.jpg?width=1024"},{"name":"Wendigo","rarity":"legendary","id":"wendigo","subtitle":"Cryptid","details":"Algonquian winter lore of the northern forests tells of a gaunt, antlered spirit of hunger said to haunt the Great Lakes woods.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wendigo%2C%20illustration.jpg?width=1024"},{"name":"Flatwoods Monster","rarity":"legendary","id":"flatwoods-monster","subtitle":"Cryptid","details":"Reports from Flatwoods, West Virginia in 1952 described a tall figure with a spade-shaped head and glowing eyes on a wooded hilltop.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/flatwoods-monster.webp"},{"name":"Jackalope","rarity":"legendary","id":"jackalope","subtitle":"Cryptid","details":"Wyoming tales tell of a jackrabbit sporting antelope horns; Douglas, Wyoming claims the first taxidermy mounts of the 1930s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jackalope%20101.jpg?width=1024"},{"name":"Hodag","rarity":"legendary","id":"hodag","subtitle":"Cryptid","details":"Rhinelander, Wisconsin lumber lore tells of a horned, spined beast Eugene Shepard claimed to capture alive in 1893.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hodag.jpg?width=1024"},{"name":"Piasa Bird","rarity":"legendary","id":"piasa-bird","subtitle":"Cryptid","details":"Illiniwek tradition told of a great man-eating bird near present-day Alton, Illinois; a painted image long marked the Mississippi bluffs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Piasa-Bird-Alton-IL.jpg?width=1024"},{"name":"Bunyip","rarity":"legendary","id":"bunyip","subtitle":"Cryptid","details":"Aboriginal Australian traditions and 19th-century reports describe a swamp creature said to lurk in billabongs and riverbeds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bunyip%201890.jpg?width=800"},{"name":"Ogopogo","rarity":"legendary","id":"ogopogo","subtitle":"Cryptid","details":"Sightings reported since the 1920s in Canada's Okanagan Lake describe a dark, serpent-like form rolling through the water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/OgoPogo%20crop.jpg?width=1024"},{"name":"Champ","rarity":"legendary","id":"champ","subtitle":"Cryptid","details":"Sightings reported since 1609 in Lake Champlain describe a long, dark, serpent-like creature, now protected by state law.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Artistic%20representation%20of%20Sandra%20Mansi%27s%201977%20photograph%20of%20%22Champ%22%20lake%20monster.jpg?width=1024"},{"name":"Mokele-mbembe","rarity":"legendary","id":"mokele-mbembe","subtitle":"Cryptid","details":"Reports from the Congo Basin describe a long-necked, sauropod-like animal said to live in remote rivers and swamp forests.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mokele-mbembe%20ill%20artlibre%20jnl.png?width=1024"},{"name":"Mapinguari","rarity":"legendary","id":"mapinguari","subtitle":"Cryptid","details":"Amazonian reports in Brazil describe a huge, shaggy, ground-sloth-like beast said to roam the deep rainforest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Megatherium.jpg?width=1024"},{"name":"Minotaur","rarity":"legendary","id":"minotaur","subtitle":"Monster","details":"In Greek myth the Minotaur, half man and half bull, was kept in the Labyrinth of Crete until the hero Theseus slew it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tondo%20Minotaur%20London%20E4%20MAN.jpg?width=1024"},{"name":"Medusa","rarity":"legendary","id":"medusa","subtitle":"Monster","details":"In Greek myth Medusa was a Gorgon whose hair was living snakes and whose gaze turned anyone who met it to stone.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caravaggio%20-%20Medusa%20-%20Google%20Art%20Project.jpg?width=1024"},{"name":"Cerberus","rarity":"legendary","id":"cerberus","subtitle":"Monster","details":"In Greek myth Cerberus, the three-headed hound of Hades, guarded the gates of the underworld so no dead soul could leave.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Herakles%20Kerberos%20Eurystheus%20Louvre%20E701.jpg?width=1024"},{"name":"Hydra","rarity":"legendary","id":"hydra","subtitle":"Monster","details":"In Greek myth the Lernaean Hydra grew two heads for every one cut off, until Heracles and Iolaus seared each stump shut.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Antonio%20del%20Pollaiolo%20-%20Hercules%20and%20the%20Hydra%20-%20WGA18031.jpg?width=1024"},{"name":"Griffin","rarity":"legendary","id":"griffin","subtitle":"Mythical Creature","details":"Greek writers told of griffins, part eagle and part lion, guarding gold at the edges of the known world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Morgan%20M.81%2C%20f.036v-grifes.jpg?width=1024"},{"name":"Chimera","rarity":"legendary","id":"chimera","subtitle":"Monster","details":"In Greek myth the Chimera joined a lion, a goat and a serpent in one fire-breathing body, slain by Bellerophon and Pegasus.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chimera%20Apulia%20Louvre%20K362.jpg?width=1024"},{"name":"Kitsune","rarity":"legendary","id":"kitsune","subtitle":"Yokai","details":"In Japanese folklore, the kitsune is a fox spirit whose wisdom and power grow with age, until it earns as many as nine tails.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yoshitoshi_-_100_Aspects_of_the_Moon_-_91.jpg?width=1024"},{"name":"Ryujin","rarity":"legendary","id":"ryujin","subtitle":"Mythical Creature","details":"In Japanese myth, Ryujin is the dragon king of the sea, ruling tides and storms from a glittering palace beneath the waves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Dragon%20King%20Ryujin%20and%20the%20Tide-controlling%20Jewels%20beneath%20the%20sea.jpg?width=1024"},{"name":"Oni","rarity":"legendary","id":"oni","subtitle":"Yokai","details":"In Japanese folklore, oni are huge, horned ogres with wild hair and clubs, said to punish the wicked and haunt the mountains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kobo_Daishi_Practicing_the_Tantra%2C_with_Demon_and_Wolf%2C_by_Hokusai.jpg?width=1024"},{"name":"Qilin","rarity":"legendary","id":"qilin","subtitle":"Mythical Creature","details":"Chinese myth tells of the qilin, a gentle, hoofed omen-beast with dragon-like features whose appearance heralds a wise ruler.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Qilin-shaped_incense_burner_1_CAC.JPG?width=1024"},{"name":"Tengu","rarity":"legendary","id":"tengu","subtitle":"Yokai","details":"In Japanese folklore, tengu are proud mountain spirits with long noses or beaks, feared as tricksters and masters of martial arts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/King%20of%20the%20tengu%20with%20Ushiwakamaru.jpg?width=1024"},{"name":"Fenrir","rarity":"legendary","id":"fenrir","subtitle":"Mythical Creature","details":"In Norse myth, the giant wolf who breaks his fetters at Ragnarök and devours Odin himself.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tyr%20and%20Fenrir-John%20Bauer.jpg?width=1024"},{"name":"Jörmungandr","rarity":"legendary","id":"jormungandr","subtitle":"Serpent","details":"In Norse myth, the world serpent coiled around Midgard, fated to slay and be slain by Thor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thor%20and%20J%C3%B6rmungandr%20by%20Fr%C3%B8lich.jpg?width=1024"},{"name":"Sleipnir","rarity":"legendary","id":"sleipnir","subtitle":"Mythical Creature","details":"In Norse myth, Odin's grey eight-legged stallion, the finest and fastest horse among gods and men.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Odin%20and%20Sleipnir%20-%20John%20Bauer.jpg?width=1024"},{"name":"Níðhöggr","rarity":"legendary","id":"nihoggr","subtitle":"Dragon","details":"In Norse myth, the dragon that gnaws the roots of Yggdrasil and feeds on the blood of the dead.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nidhogg.png?width=1024"},{"name":"Leviathan","rarity":"legendary","id":"leviathan","subtitle":"Sea Monster","details":"Ancient Hebrew tradition told of Leviathan, a mighty sea serpent subdued at the dawn of creation.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/122.The%20Destruction%20of%20Leviathan.jpg?width=800"},{"name":"Roc","rarity":"legendary","id":"roc","subtitle":"Mythical Creature","details":"In Arabian tales, the Roc was a bird so vast it could carry off elephants in its talons.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Edward%20Julius%20Detmold49.jpg?width=1024"},{"name":"Anzu","rarity":"legendary","id":"anzu","subtitle":"Mythical Creature","details":"In Mesopotamian myth, Anzu was a lion-headed storm eagle who stole the Tablet of Destinies.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Frieze%20of%20Imdugud%20%28Anzu%29%20grasping%20a%20pair%20of%20deer%2C%20from%20Tell%20Al-Ubaid..JPG?width=1024"},{"name":"Simurgh","rarity":"legendary","id":"simurgh","subtitle":"Mythical Creature","details":"In Persian legend, the Simurgh is a wise, benevolent winged creature that raised the hero Zal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Basawan.%20The%20Flight%20of%20the%20Simurgh.%20ca.%201590%2C%20Sadruddin%20Aga%20Khan%20Collection.jpg?width=500"},{"name":"Hopkinsville Goblins","rarity":"epic","id":"hopkinsville-goblins","subtitle":"Cryptid","details":"Reports from Kelly, Kentucky in 1955 described small glowing figures that approached a farmhouse through the night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hopkinsville%20goblin.png?width=800"},{"name":"Dover Demon","rarity":"epic","id":"dover-demon","subtitle":"Cryptid","details":"Dover, Massachusetts teens in 1977 reported a hairless, large-headed creature with glowing orange eyes seen over two nights.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dover%20Demon.png?width=1024"},{"name":"Loveland Frogman","rarity":"epic","id":"loveland-frogman","subtitle":"Cryptid","details":"Loveland, Ohio reports from 1955 and 1972 described bipedal frog-like figures, one said to brandish a wand-like object.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Loveland%20frog.png?width=800"},{"name":"Ozark Howler","rarity":"epic","id":"ozark-howler","subtitle":"Cryptid","details":"Ozark Mountain lore tells of a shaggy, horned beast whose eerie cry is said to echo through Arkansas and Missouri hollows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ozark%20Howler%20Watercolor%20Painting.jpg?width=1024"},{"name":"Skunk Ape","rarity":"epic","id":"skunk-ape","subtitle":"Cryptid","details":"Florida swamp reports describe a tall, foul-smelling ape-like figure, most often placed in the Everglades and Big Cypress.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Florida%20Skunk%20Ape%20-%20panoramio.jpg?width=800"},{"name":"Rougarou","rarity":"epic","id":"rougarou","subtitle":"Cryptid","details":"Cajun Louisiana tradition tells of a wolf-headed man said to prowl the bayous and enforce Lenten rules on the unwary.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rougarou.jpg?width=1024"},{"name":"Mishipeshu","rarity":"epic","id":"mishipeshu","subtitle":"Cryptid","details":"Ojibwe tradition tells of a horned underwater panther in the deep waters of Lake Superior, honored in ancient rock paintings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mississippians%20underwater%20panther%20HRoe%202005.jpg?width=1024"},{"name":"Dzunukwa","rarity":"epic","id":"dzunukwa","subtitle":"Cryptid","details":"Kwakwaka'wakw tradition tells of a giant wild woman of the British Columbia woods, depicted on carved masks and feast dishes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dzunu%E1%B8%B5%CC%93wa%2C%20also%20Tsonoqua%2C%20Tsonokwa.jpg?width=1024"},{"name":"Mogollon Monster","rarity":"epic","id":"mogollon-monster","subtitle":"Cryptid","details":"Arizona reports along the Mogollon Rim describe a tall, hairy wild man said to roam the pines around Payson.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mogollon%20Monster%20Carving.jpg?width=800"},{"name":"Thylacine","rarity":"epic","id":"thylacine","subtitle":"Cryptid","details":"Declared extinct after the last known animal died in Tasmania in 1936, yet reported sightings in Australia have continued since.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thylacinus%20cropped.png?width=800"},{"name":"Kongamato","rarity":"epic","id":"kongamato","subtitle":"Cryptid","details":"Reports from Zambia's Jiundu swamps describe a huge flying reptile with leathery wings, said to resemble a pterosaur.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kongamato.png?width=800"},{"name":"Beast of Gévaudan","rarity":"epic","id":"beast-of-gevaudan","subtitle":"Cryptid","details":"Between 1764 and 1767, a wolf-like beast was blamed for deadly attacks in France's Gévaudan region before hunts ended it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gevaudanwolf.jpg?width=1024"},{"name":"Orang Pendek","rarity":"epic","id":"orang-pendek","subtitle":"Cryptid","details":"Sightings reported for a century in Sumatra's Kerinci forests describe a short, upright ape said to walk on two legs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Orang%20Pendek.png?width=450"},{"name":"Mongolian Death Worm","rarity":"epic","id":"mongolian-death-worm","subtitle":"Cryptid","details":"Gobi Desert reports from Mongolia describe a thick, red, worm-like creature said to spit venom and jolt with electricity.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Allghoikhorkhoi.jpg?width=1024"},{"name":"Grootslang","rarity":"epic","id":"grootslang","subtitle":"Cryptid","details":"South African legend tells of a gigantic serpent with elephant features said to guard diamonds in a Richtersveld cave.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grootslang.jpg?width=1024"},{"name":"Nahuelito","rarity":"epic","id":"nahuelito","subtitle":"Cryptid","details":"Sightings reported since 1922 in Argentina's Nahuel Huapi Lake describe a long-necked, plesiosaur-like creature.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nahuelito%20%28artistic%20rendition%29.jpg?width=1024"},{"name":"Yowie","rarity":"epic","id":"yowie","subtitle":"Cryptid","details":"Reports from Australia's bush describe a tall, hairy, ape-like figure, kin to wildman traditions around the world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yowie-statue-Kilcoy-Queensland.JPG?width=1024"},{"name":"Cyclops","rarity":"epic","id":"cyclops","subtitle":"Monster","details":"In Greek myth the Cyclopes were one-eyed giants; the shepherd Polyphemus trapped Odysseus and his men in his cave.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Redon.cyclops.jpg?width=1024"},{"name":"Pegasus","rarity":"epic","id":"pegasus","subtitle":"Mythical Creature","details":"In Greek myth Pegasus, the winged horse born from Medusa's blood, carried the hero Bellerophon into battle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pelike%20Bellerophon%20Louvre%20G535.jpg?width=1024"},{"name":"Centaur","rarity":"epic","id":"centaur","subtitle":"Mythical Creature","details":"In Greek myth centaurs, half man and half horse, roamed Thessaly's mountains; wise Chiron alone was famed for gentleness.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Terracotta%20lekythos%20%28oil%20flask%29%20with%20centaur%20battling%20a%20warrior%20MET%20DP161810.jpg?width=1024"},{"name":"Sphinx","rarity":"epic","id":"sphinx","subtitle":"Mythical Creature","details":"In Greek myth the Sphinx of Thebes devoured travellers who could not answer her riddle, until Oedipus solved it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sphinx%20CdM%20Paris%20DeRidder865%20n2.jpg?width=1024"},{"name":"Typhon","rarity":"epic","id":"typhon","subtitle":"Monster","details":"In Greek myth Typhon, a hundred-headed storm monster, was the most terrible foe the Olympian gods ever faced.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zeus%20Typhon%20Staatliche%20Antikensammlungen%20596.jpg?width=1024"},{"name":"Scylla","rarity":"epic","id":"scylla","subtitle":"Monster","details":"In Greek myth Scylla, a six-headed monster on her rock, snatched sailors from ships passing through the strait.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Scylla%20Louvre%20CA1341.jpg?width=1024"},{"name":"Basilisk","rarity":"epic","id":"basilisk","subtitle":"Monster","details":"Medieval bestiaries described the basilisk, king of serpents, whose gaze and breath were said to kill, hatched from a cockerel's egg.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aberdeen%20Bestiary%20Basilisk.jpg?width=800"},{"name":"Manticore","rarity":"epic","id":"manticore","subtitle":"Monster","details":"Greek writers, retelling Persian tales, described the manticore: a man's face, a lion's body and a sting-bearing tail.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/manticore.webp"},{"name":"Wyvern","rarity":"epic","id":"wyvern","subtitle":"Mythical Creature","details":"Medieval European heraldry and tale gave the wyvern two legs and barbed, dragon-like wings, unlike its four-legged kin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wrest%20Park%20Wyvern.jpg?width=1024"},{"name":"Kappa","rarity":"epic","id":"kappa","subtitle":"Yokai","details":"In Japanese folklore, the kappa is a river imp with a water-filled dish on its head; if the water spills, its strength drains away.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kyoka_Hyaku-Monogatari_Kappa.jpg?width=1024"},{"name":"Azure Dragon","rarity":"epic","id":"azure-dragon","subtitle":"Mythical Creature","details":"Chinese myth names the Azure Dragon one of the Four Symbols, guardian of the east, spring, and the rising storm clouds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Azure%20Dragon.jpg?width=1024"},{"name":"Fenghuang","rarity":"epic","id":"fenghuang","subtitle":"Mythical Creature","details":"Chinese myth tells of the fenghuang, a radiant bird of virtue and grace whose rare appearance promises peace and good rule.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yu%20Sheng%20-%20Fenghuang%20-%2018th-century.jpg?width=1024"},{"name":"Naga","rarity":"epic","id":"naga","subtitle":"Mythical Creature","details":"In Hindu and Southeast Asian tradition, naga are powerful serpent beings who guard waters, treasures, and the underworld.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Naga182.JPG?width=1024"},{"name":"Garuda","rarity":"epic","id":"garuda","subtitle":"Mythical Creature","details":"In Hindu tradition, Garuda is the mighty eagle-like mount of Vishnu, a sworn enemy of serpents and a symbol of swiftness.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Garuda_by_Hyougushi_in_Delhi.jpg?width=1024"},{"name":"Gumiho","rarity":"epic","id":"gumiho","subtitle":"Mythical Creature","details":"Korean folklore tells of the gumiho, a nine-tailed fox that can take human form and is said to lure the unwary with its beauty.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/KUMIHO.jpg?width=1024"},{"name":"Dragon King","rarity":"epic","id":"dragon-king","subtitle":"Mythical Creature","details":"Chinese myth tells of the Dragon Kings, rulers of the four seas who command rain, rivers, and the weather from crystal palaces.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%E6%B5%B7%E9%BE%8D%E7%8E%8B%2C%20British%20Museum.jpg?width=1024"},{"name":"Yuki-onna","rarity":"epic","id":"yuki-onna","subtitle":"Yokai","details":"In Japanese folklore, Yuki-onna is a pale snow woman who appears in blizzards, her breath cold enough to freeze travelers solid.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Suushi_Yuki-onna.jpg?width=1024"},{"name":"Fafnir","rarity":"epic","id":"fafnir","subtitle":"Dragon","details":"In Norse myth, the dwarf-turned-dragon guarding cursed gold until Sigurd pierces his heart.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sigurd%20kills%20Fafnir%20by%20Rackham.jpg?width=1024"},{"name":"Banshee","rarity":"epic","id":"banshee","subtitle":"Spirit","details":"Irish folklore tells of the wailing woman whose cry foretells a death in an old family.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Banshee.jpg?width=1024"},{"name":"Kelpie","rarity":"epic","id":"kelpie","subtitle":"Mythical Creature","details":"Scottish tales describe the shape-shifting water horse that lures riders, then drags them under.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kelpie%201%2C%20Falkirk.jpg?width=1024"},{"name":"Frost Giant","rarity":"epic","id":"frost-giant","subtitle":"Giant","details":"In Norse myth, the Jötnar of Jötunheim embody winter's hunger and war with the gods.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/J%C3%A4tten%20som%20sov%20i%20femtusen%20%C3%A5r%20(cropped).jpg?width=1024"},{"name":"Selkie","rarity":"epic","id":"selkie","subtitle":"Mythical Creature","details":"Celtic folklore tells of seal-folk who shed their skins to walk ashore as beautiful humans.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Selkie%20by%20Carolyn%20Emerick%202013.jpg?width=800"},{"name":"Aspidochelone","rarity":"epic","id":"aspidochelone","subtitle":"Sea Monster","details":"Medieval bestiaries told of a whale so huge that sailors mistook its back for an island.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Two%20Fishermen%20on%20an%20Aspidochelone%2C%20c.%201270%20%28cropped%29.JPG?width=800"},{"name":"Hafgufa","rarity":"epic","id":"hafgufa","subtitle":"Sea Monster","details":"Norse seafarers' accounts described Hafgufa, an immense sea monster that swallowed ships and whales.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aspidochelone2-gks1633-danish-royal-library.jpg?width=1024"},{"name":"Ziz","rarity":"epic","id":"ziz","subtitle":"Mythical Creature","details":"Jewish legend told of the Ziz, a giant griffin-like bird whose wings could darken the sun.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/ziz.webp"},{"name":"Quetzalcoatl","rarity":"epic","id":"quetzalcoatl","subtitle":"Mythical Creature","details":"In Aztec tradition, Quetzalcoatl is the feathered serpent, a creator god of wind and learning.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Teotihuacan%2011%20templo%20de%20Quetzalcoatl%20cabeza%20de%20serpiente%20emplumada.JPG?width=1024"},{"name":"Rainbow Serpent","rarity":"epic","id":"rainbow-serpent","subtitle":"Mythical Creature","details":"In Aboriginal Australian tradition, the Rainbow Serpent is an ancestral creator tied to water and rain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Namaroto%20spirits%20and%20the%20Rainbow%20Serpent%20Burlung.jpg?width=1024"},{"name":"Umibozu","rarity":"epic","id":"umibozu","subtitle":"Sea Monster","details":"Japanese sailors' tales told of Umibozu, a bald sea spirit whose rising could calm or wreck ships.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kuwana%20-%20The%20sailor%20Tokuso%20and%20the%20sea%20monster.jpg?width=800"},{"name":"Slide-Rock Bolter","rarity":"rare","id":"slide-rock-bolter","subtitle":"Cryptid","details":"Colorado lumber lore tells of a huge whale-like beast that slides down mountain slopes on its hooked tail to snatch tourists.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fearsome%20Creatures%20of%20the%20Lumberwoods%2C%20with%20a%20Few%20Desert%20and%20Mountain%20Beasts%20%28page%2026%20crop%29.jpg?width=1024"},{"name":"Snallygaster","rarity":"rare","id":"snallygaster","subtitle":"Cryptid","details":"Maryland lore from the 1700s tells of a winged, tentacled beast said to swoop over Middletown Valley farms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Snallygaster-image.png?width=1024"},{"name":"Wampus Cat","rarity":"rare","id":"wampus-cat","subtitle":"Cryptid","details":"Appalachian and Cherokee tales tell of a fearsome wild cat said to stalk the mountains of Tennessee and North Carolina.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wampus%20cat.jpg?width=1024"},{"name":"Crawfordsville Monster","rarity":"rare","id":"crawfordsville-monster","subtitle":"Cryptid","details":"Crawfordsville, Indiana reports in 1891 described a great white serpent-like form writhing through the sky.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crawfordsville%20monster.jpg?width=1024"},{"name":"Batsquatch","rarity":"rare","id":"batsquatch","subtitle":"Cryptid","details":"Reports near Mount St. Helens after the 1980 eruption described a muscular flying creature with bat wings and a wolf-like head.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Batsquatch.jpg?width=1024"},{"name":"Uktena","rarity":"rare","id":"uktena","subtitle":"Cryptid","details":"Cherokee tradition tells of a great horned serpent with a crystal in its forehead, said to haunt rivers and mountain pools.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Winged%20serpent%20HRoe%202008%2001.jpg?width=1024"},{"name":"Sisiutl","rarity":"rare","id":"sisiutl","subtitle":"Cryptid","details":"Kwakwaka'wakw tradition tells of a supernatural two-headed serpent, carved on masks and dance boards in British Columbia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sisiutl%20mask.jpg?width=1024"},{"name":"Huxwhukw","rarity":"rare","id":"huxwhukw","subtitle":"Cryptid","details":"Kwakwaka'wakw winter ceremonial tradition tells of Huxwhukw, a giant supernatural crane with a long, sky-snapping beak.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crooked%20beak%20mask%20and%20Huxwhukw%20mask%2C%20by%20Yakuglas%20Charlie%20James%20%281875-1938%29%2C%20Kwakwka%27wakw%2C%20c.%201900%2C%20red%20cedar%2C%20red%20cedar%20bark%2C%20feathers%2C%20paint%2C%20string%20-%20Portland%20Art%20Museum%20-%20Portland%2C%20Oregon%20-%20DSC09113.jpg?width=1024"},{"name":"Vegetable Man","rarity":"rare","id":"vegetable-man","subtitle":"Cryptid","details":"A 1968 report from Fairmont, West Virginia described a tall, plant-like figure with suction-cup fingers and a piercing voice.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Vegetable%20Man%20of%20West%20Virginia%20%28Full%20Body%20Depiction%29.jpg?width=1024"},{"name":"Montauk Monster","rarity":"rare","id":"montauk-monster","subtitle":"Cryptid","details":"In 2008 a strange hairless carcass washed ashore at Montauk, New York, sparking worldwide debate over what it had been.","image":"https://en.wikipedia.org/wiki/Special:FilePath/RhodeislandMonster.jpg?width=1024"},{"name":"Cadejo","rarity":"rare","id":"cadejo","subtitle":"Cryptid","details":"Central American tradition tells of a great black dog with glowing red eyes said to follow travelers on night roads.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cadejo.JPG?width=1024"},{"name":"Siguanaba","rarity":"rare","id":"siguanaba","subtitle":"Cryptid","details":"El Salvador and Honduras tradition tells of a figure seen washing at rivers who is said to turn a horse's face to her victims.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Siguanaba.JPG?width=1024"},{"name":"Kusshie","rarity":"rare","id":"kusshie","subtitle":"Cryptid","details":"Reports since 1973 describe a long-necked creature in Japan's Lake Kussharo, where a statue now stands on the shore.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kussharoko%20Teshikaga%20Hokkaido%20Japan10n.jpg?width=1024"},{"name":"Memphré","rarity":"rare","id":"memphre","subtitle":"Cryptid","details":"Reports since 1816 describe a serpent-like creature in Lake Memphremagog, straddling the Quebec and Vermont border.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Le%20Monstre%20du%20Memphr%C3%A9%20en%202025.jpg?width=1024"},{"name":"Hoan Kiem Turtle","rarity":"rare","id":"hoan-kiem-turtle","subtitle":"Cryptid","details":"Hanoi legend tells of a giant turtle in Hoan Kiem Lake that returned a magic sword; real giant turtles lived there for centuries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/R%C3%B9a%20H%E1%BB%93%20G%C6%B0%C6%A1m.jpg?width=1024"},{"name":"Almas","rarity":"rare","id":"almas","subtitle":"Cryptid","details":"Wildman reports from Mongolia and Central Asia describe a hairy, human-like figure said to flee from settlements.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Engraving%20of%20orang-outang%2C%20standing.%20Wellcome%20L0010927.jpg?width=1024"},{"name":"Hibagon","rarity":"rare","id":"hibagon","subtitle":"Cryptid","details":"Reports from 1970 around Japan's Mount Hiba describe a short, gorilla-like ape said to leave oversized footprints.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Penny%20Magazine%201835%20268%20The%20Orang-Outang.jpg?width=1024"},{"name":"Yeren","rarity":"rare","id":"yeren","subtitle":"Cryptid","details":"Reports from China's Shennongjia forests describe a tall, reddish-haired wildman said to walk upright in the mountains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Engraving%20of%20an%20orang-outang.%20Wellcome%20L0010928.jpg?width=800"},{"name":"Minhocão","rarity":"rare","id":"minhocao","subtitle":"Cryptid","details":"Brazilian reports describe a gigantic, earthworm-like burrower said to shift rivers and trench the wetlands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Giant%20Earthworm%20%2824663328188%29.jpg?width=1024"},{"name":"Nandi Bear","rarity":"rare","id":"nandi-bear","subtitle":"Cryptid","details":"Reports from western Kenya describe a fierce, bear-like beast said to raid livestock, though Kenya has no native bears.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%D8%B6%D8%A8%D8%B9%20%D9%85%D8%AE%D8%B7%D8%B7%20%22Hyaena%20hyaena%22%2005.jpg?width=1024"},{"name":"Spring-heeled Jack","rarity":"rare","id":"spring-heeled-jack","subtitle":"Cryptid","details":"Victorian England panicked over reports of a leaping, clawed figure in a black cloak, first described in London in 1837.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/spring-heeled-jack.webp"},{"name":"El Cuero","rarity":"rare","id":"el-cuero","subtitle":"Cryptid","details":"Reports from lakes in Chile and Argentina describe a flat, ray-like creature said to drag prey beneath the surface.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/South%20American%20Freshwater%20Stingray%20%28Potamotrygon%20motoro%29%20%286978486064%29.jpg?width=1024"},{"name":"Harpy","rarity":"rare","id":"harpy","subtitle":"Monster","details":"In Greek myth harpies were winged women who snatched food and people away, agents of sudden storm winds.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/harpy.webp"},{"name":"Siren","rarity":"rare","id":"siren","subtitle":"Mythical Creature","details":"In Greek myth the Sirens, part woman and part bird, sang from their island and lured sailors onto the rocks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/NAMA%20Sir%C3%A8ne.jpg?width=1024"},{"name":"Charybdis","rarity":"rare","id":"charybdis","subtitle":"Monster","details":"In Greek myth Charybdis, a vast whirlpool monster, swallowed and spewed the sea thrice daily opposite Scylla's rock.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Johann%20Heinrich%20F%C3%BCssli%20054.jpg?width=1024"},{"name":"Echidna","rarity":"rare","id":"echidna","subtitle":"Monster","details":"In Greek myth Echidna, half woman and half serpent, was called the mother of monsters, bearing Hydra, Cerberus and more.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Echidna%20-%20Parco%20dei%20Mostri%20-%20Bomarzo%2C%20Italy%20-%20DSC02642.jpg?width=1024"},{"name":"Nemean Lion","rarity":"rare","id":"nemean-lion","subtitle":"Monster","details":"In Greek myth the Nemean Lion's hide no blade could pierce, until Heracles strangled it for his first labour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mosaico%20Trabajos%20H%C3%A9rcules%20%28M.A.N.%20Madrid%29%2001.jpg?width=1024"},{"name":"Ladon","rarity":"rare","id":"ladon","subtitle":"Monster","details":"In Greek myth Ladon, the hundred-eyed dragon, coiled round the golden apple tree in the garden of the Hesperides.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Herakles%20Ladon%20Staatliche%20Antikensammlungen%20SL89.jpg?width=1024"},{"name":"Talos","rarity":"rare","id":"talos","subtitle":"Mythical Creature","details":"In Greek myth Talos was a giant of bronze who circled Crete thrice daily, hurling rocks at approaching ships.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Phaistos%20-%20M%C3%BCnzkabinett%2C%20Berlin%20-%205480082.jpg?width=1024"},{"name":"Cockatrice","rarity":"rare","id":"cockatrice","subtitle":"Monster","details":"Medieval bestiaries told of the cockatrice, part cockerel and part serpent, whose look was said to turn victims to stone.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/John%20Vinycomb%20-%20Cockatrice%2C%201906.jpg?width=1024"},{"name":"Tarasque","rarity":"rare","id":"tarasque","subtitle":"Monster","details":"French legend told of the Tarasque, a dragon-like river monster of the Rhone, tamed by Saint Martha's prayer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tarasque%20et%20Sainte%20Marthe%20Leblond.jpg?width=800"},{"name":"Questing Beast","rarity":"rare","id":"questing-beast","subtitle":"Mythical Creature","details":"Arthurian romance told of the Questing Beast, part serpent, stag and lion, hunted in vain by King Pellinore's line.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Arthur%20and%20the%20Questing%20Beast%20%28full%29.jpg?width=1024"},{"name":"Lindworm","rarity":"rare","id":"lindworm","subtitle":"Monster","details":"Central European tales told of lindworms, wingless two-legged serpents that grew larger the more they ate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/John%20Bauer%2C%201911%20%28cropped%2C%20no%20signature%29.jpg?width=800"},{"name":"Antaeus","rarity":"rare","id":"antaeus","subtitle":"Monster","details":"In Greek myth Antaeus, a Libyan giant, drew strength from the earth his mother, and wrestled every traveller he met.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Herakles%20Antaios%20Louvre%20G103.jpg?width=1024"},{"name":"Tanuki","rarity":"rare","id":"tanuki","subtitle":"Yokai","details":"In Japanese folklore, the bake-danuki is a mischievous raccoon-dog shapeshifter that delights in tricks, disguises, and drumming on its belly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yoshitoshi%20Bunbuku%20Chagama.jpg?width=1024"},{"name":"Zhong Kui","rarity":"rare","id":"zhong-kui","subtitle":"Mythical Creature","details":"Chinese folklore honors Zhong Kui, a fierce bearded scholar-spirit whose image is hung on doors to frighten demons and ill fortune away.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zhong%20Kui%20the%20Demon%20Queller%20with%20Five%20Bats.jpg?width=1024"},{"name":"Jorogumo","rarity":"rare","id":"jorogumo","subtitle":"Yokai","details":"In Japanese folklore, the jorogumo is a spider that, after 400 years, can take the form of a beautiful woman to ensnare her prey.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SekienJorogumo.jpg?width=1024"},{"name":"Nue","rarity":"rare","id":"nue","subtitle":"Yokai","details":"In Japanese folklore, the nue is a chimera with a monkey's head, tiger's limbs, and a snake for a tail, whose cry brings misfortune.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kuniyoshi_Taiba_%28The_End%29.jpg?width=1024"},{"name":"Pixiu","rarity":"rare","id":"pixiu","subtitle":"Mythical Creature","details":"Chinese myth tells of the pixiu, a winged lion-like beast said to devour wealth and guard it, making it an emblem of prosperity.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tomb_Yongning_of_the_Ts%27en_Dynasty.JPG?width=1024"},{"name":"Shuten-doji","rarity":"rare","id":"shuten-doji","subtitle":"Yokai","details":"In Japanese folklore, Shuten-doji is the drunken oni king of Mount Oe, whose reign of terror was ended by the hero Raiko and his men.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Iwaya%281927%29-p000-frontispiece-oeyama.jpg?width=1024"},{"name":"Rakshasa","rarity":"rare","id":"rakshasa","subtitle":"Mythical Creature","details":"In Hindu tradition, rakshasas are powerful shape-shifting beings, often depicted as fierce guardians or as foes of gods and heroes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_three-headed_rakshasa_Trishiras_sits_in_lalitasana_on_a_throne_facing_a_fire_altar_in_which_a_severed_head_is_burning.jpg?width=1024"},{"name":"Nurarihyon","rarity":"rare","id":"nurarihyon","subtitle":"Yokai","details":"In Japanese folklore, Nurarihyon is a sly, bald-headed yokai said to slip uninvited into homes and command processions of spirits.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/10.Nurarihyon.jpg?width=1024"},{"name":"Gashadokuro","rarity":"rare","id":"gashadokuro","subtitle":"Yokai","details":"In Japanese folklore, the gashadokuro is a towering skeleton formed from the bones of the unburied dead, rattling as it hunts at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Takiyasha_the_Witch_and_the_Skeleton_Spectre%2C_by_Utagawa_Kuniyoshi.jpg?width=1024"},{"name":"Bai Ze","rarity":"rare","id":"bai-ze","subtitle":"Mythical Creature","details":"Chinese myth tells of Bai Ze, a wise, many-eyed beast that knows every spirit and ghost, and shared that knowledge with the Yellow Emperor.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/bai-ze.webp"},{"name":"Dullahan","rarity":"rare","id":"dullahan","subtitle":"Mythical Creature","details":"Irish folklore tells of the headless rider who carries his grinning head and calls the dying.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Croker(1834)Fairy%20Legends%20p0239-dullahan.jpg?width=1024"},{"name":"Each-Uisge","rarity":"rare","id":"each-uisge","subtitle":"Mythical Creature","details":"Scottish tales describe the cruelest water horse, which devours its victims whole once they touch it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Theodor%20Kittelsen%20-%20N%C3%B8kken%20som%20hvit%20hest.jpg?width=1024"},{"name":"Cat Sìth","rarity":"rare","id":"cat-sith","subtitle":"Mythical Creature","details":"Scottish folklore tells of the fairy cat, jet black save a white spot on its chest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Page%20158%20illustration%20in%20More%20English%20Fairy%20Tales.png?width=1024"},{"name":"Cù Sìth","rarity":"rare","id":"cu-sith","subtitle":"Mythical Creature","details":"Scottish tales describe the huge green fairy hound whose three barks foretell a listener's death.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cu%20Sidhe's%20Graveyard%20by%20Inari123.jpg?width=1024"},{"name":"Púca","rarity":"rare","id":"puca","subtitle":"Mythical Creature","details":"Irish folklore tells of the shape-shifting goblin of the fields, sometimes horse, sometimes hare.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pwca%20Wirt%20Sikes%20British%20Goblins%201880%20(cropped).png?width=1024"},{"name":"Merrow","rarity":"rare","id":"merrow","subtitle":"Mythical Creature","details":"Irish folklore tells of the sea-folk with green hair and red-feathered caps who live beneath the waves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Clonfert%20Cathedral%20Mermaid%202009%2009%2017.jpg?width=800"},{"name":"Huginn & Muninn","rarity":"rare","id":"huginn-muninn","subtitle":"Mythical Creature","details":"In Norse myth, Odin's two ravens fly the world each dawn and return to whisper the news.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Odin%20hrafnar.jpg?width=1024"},{"name":"Auðumbla","rarity":"rare","id":"auumbla","subtitle":"Mythical Creature","details":"In Norse myth, the primeval cow whose licking freed the first gods from the ice.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/audumla.webp"},{"name":"Tiamat","rarity":"rare","id":"tiamat","subtitle":"Sea Monster","details":"In Babylonian myth, Tiamat is the primordial salt-sea mother, mother of the first gods.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chaos%20Monster%20and%20Sun%20God.png?width=500"},{"name":"Gloucester Sea Serpent","rarity":"rare","id":"gloucester-sea-serpent","subtitle":"Sea Monster","details":"Reports off Gloucester in 1817 described a huge humped sea serpent seen by hundreds of witnesses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1817%20Gloucester%20sea%20serpent.jpg?width=1024"},{"name":"Hans Egede Sea Serpent","rarity":"rare","id":"hans-egede-sea-serpent","subtitle":"Sea Monster","details":"In 1734, missionary Hans Egede reported a great sea serpent rearing beside his ship off Greenland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hans%20Egede%20sea%20serpent%201734.jpg?width=1024"},{"name":"Bake-Kujira","rarity":"rare","id":"bake-kujira","subtitle":"Sea Monster","details":"In Japanese folklore, the Bake-Kujira is a ghostly whale skeleton said to appear off the Shimane coast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Whale%20skeleton.png?width=1024"},{"name":"Iku-Turso","rarity":"rare","id":"iku-turso","subtitle":"Sea Monster","details":"In Finnish tradition, Iku-Turso is an ancient sea monster of the deep, father of diseases.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/iku-turso.webp"},{"name":"Camazotz","rarity":"rare","id":"camazotz","subtitle":"Mythical Creature","details":"In Maya tradition, Camazotz is a bat god of night, death, and sacrifice in the underworld.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Honduras-0334%20%282213598531%29.jpg?width=1024"},{"name":"Buraq","rarity":"rare","id":"buraq","subtitle":"Mythical Creature","details":"In Islamic tradition, the Buraq is a winged steed that carried the Prophet on the Night Journey.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Al%20Buraq%20-%201770-75.jpg?width=1024"},{"name":"Taniwha","rarity":"rare","id":"taniwha","subtitle":"Sea Monster","details":"In Maori tradition, taniwha are powerful water beings that guard or threaten those who travel rivers and coasts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ureia2.jpg?width=500"},{"name":"Pukwudgie","rarity":"uncommon","id":"pukwudgie","subtitle":"Cryptid","details":"Wampanoag and Algonquian tradition tells of small, grey wild folk of the woods, said to be able to vanish at will.","image":"https://raw.githubusercontent.com/FAshe27/card-pack-opener/main/assets/sets/cryptids/images/pukwudgie.webp"},{"name":"Pedro Mountains Mummy","rarity":"uncommon","id":"pedro-mountains-mummy","subtitle":"Cryptid","details":"In 1932 miners in Wyoming's Pedro Mountains found a tiny mummified figure, linked by some to Shoshone tales of little people.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20San%20Pedro%20Mountain%20Mummy.jpg?width=1024"},{"name":"Not Deer","rarity":"uncommon","id":"not-deer","subtitle":"Cryptid","details":"Modern Appalachian accounts describe deer-like animals that move wrong: too many joints, too-bold eyes, a gaze like a predator's.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Not-deer%20cryptid.png?width=800"},{"name":"Flying Head","rarity":"uncommon","id":"flying-head","subtitle":"Cryptid","details":"Haudenosaunee tradition tells of a ravenous flying head, borne on storm winds, that was said to devour everything in its path.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flying-head-cornplanter.jpg?width=1024"},{"name":"Tupilaq","rarity":"uncommon","id":"tupilaq","subtitle":"Cryptid","details":"Greenlandic Inuit tradition tells of the tupilaq, a monster figure assembled and sent to seek out an enemy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tupilak%203.jpg?width=1024"},{"name":"Nahual","rarity":"uncommon","id":"nahual","subtitle":"Cryptid","details":"Mexican tradition tells of the nahual, a person said to take animal form at night; Oaxaca carvers render nahuales in wood.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/National%20Museum%20of%20Ethnology%2C%20Osaka%20-%20Wood%20carving%20%28nahual%29%20-%20Oaxaca%20in%20Mexico%20-%20Made%20by%20Ang%C3%A9lico%20Jim%C3%A9nez%2C%20Isa%C3%ADas%20Jim%C3%A9nez%20and%20Manuel%20Jim%C3%A9nez%20-%20Collected%20in%202010.jpg?width=1024"},{"name":"El Sombrerón","rarity":"uncommon","id":"el-sombreron","subtitle":"Cryptid","details":"Guatemalan tradition tells of a small man in an enormous hat who is said to serenade sleepers and braid horses' manes by night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sombreron.JPG?width=1024"},{"name":"Nulmal","rarity":"uncommon","id":"nulmal","subtitle":"Cryptid","details":"Kwakwaka'wakw winter ceremonial tradition includes Nulmal, the fool dancer, whose great carved mask is worn to keep order.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mask%20of%20Nulmal%2C%20one%20of%20the%20loading%20characters%20in%20the%20winter%20ceremonials.jpg?width=1024"},{"name":"Jake the Alligator Man","rarity":"uncommon","id":"jake-the-alligator-man","subtitle":"Cryptid","details":"At Marsh's Free Museum in Long Beach, Washington, Jake - half man, half alligator - has drawn the curious for generations.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jake%20The%20Alligator%20Man.jpg?width=1024"},{"name":"Feejee Mermaid","rarity":"uncommon","id":"feejee-mermaid","subtitle":"Cryptid","details":"P.T. Barnum's 1842 American Museum exhibit, the Feejee Mermaid, drew crowds in New York; the specimen survives at Harvard.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Feejee%20Mermaid%2C%20shown%20in%20P.T.%20Barnum%27s%20American%20Museum%2C%201842%2C%20as%20leased%20from%20Moses%20Kimball%20of%20the%20Boston%20Museum%2C%20papier-mache%20-%20Peabody%20Museum%2C%20Harvard%20University%20-%20DSC06154.jpg?width=1024"},{"name":"Cardiff Giant","rarity":"uncommon","id":"cardiff-giant","subtitle":"Cryptid","details":"Unearthed at Cardiff, New York in 1869, the ten-foot 'petrified man' drew thousands before it was confessed a carved hoax.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cardiff%20Giant%202.jpg?width=1024"},{"name":"Menehune","rarity":"uncommon","id":"menehune","subtitle":"Cryptid","details":"Hawaiian tradition tells of the Menehune, small master builders said to raise fishponds and temples in a single night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Menehune%20%288039308233%29.jpg?width=1024"},{"name":"Itzpapalotl","rarity":"uncommon","id":"itzpapalotl","subtitle":"Cryptid","details":"Aztec tradition tells of Itzpapalotl, the obsidian butterfly - a skeletal, clawed being of the night sky in codex paintings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Itzpapalotl%201.jpg?width=1024"},{"name":"Tzitzimitl","rarity":"uncommon","id":"tzitzimitl","subtitle":"Cryptid","details":"Aztec tradition tells of the tzitzimime, skeletal star beings said to descend during eclipses, painted in the codices.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tzitzimitl.jpg?width=1024"},{"name":"Tlaltecuhtli","rarity":"uncommon","id":"tlaltecuhtli","subtitle":"Cryptid","details":"Aztec tradition tells of Tlaltecuhtli, the great earth monster whose carved image was unearthed beside Mexico City's Templo Mayor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monolito%20de%20Tlaltecuhtli%20%28crop%29%20-%20Museo%20del%20Templo%20Mayor%20-%20Mexico%202024.jpg?width=1024"},{"name":"Hugag","rarity":"uncommon","id":"hugag","subtitle":"Cryptid","details":"Lake States lumber lore tells of a huge beast with jointless legs that cannot lie down and sleeps leaning against trees.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hugag.jpg?width=1024"},{"name":"Gumberoo","rarity":"uncommon","id":"gumberoo","subtitle":"Cryptid","details":"Pacific Coast lumber lore tells of a hairless, rubber-skinned bear-like beast off which bullets are said to bounce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gumberoo.jpg?width=1024"},{"name":"Snoligoster","rarity":"uncommon","id":"snoligoster","subtitle":"Cryptid","details":"Southern cypress-swamp lumber lore tells of a vast alligator-like beast that propels itself with a tail like a propeller.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fearsome%20Creatures%20of%20the%20Lumberwoods%2C%20with%20a%20Few%20Desert%20and%20Mountain%20Beasts%20%28page%2020%20crop%29.jpg?width=1024"},{"name":"Snow Wasset","rarity":"uncommon","id":"snow-wasset","subtitle":"Cryptid","details":"Northern lumber lore tells of a white, legless wasset that is said to hunt beneath the snow and vanish with the spring thaw.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fearsome%20Creatures%20of%20the%20Lumberwoods%2C%20with%20a%20Few%20Desert%20and%20Mountain%20Beasts%20%28page%2044%20crop%29.jpg?width=1024"},{"name":"Hyampom Hog Bear","rarity":"uncommon","id":"hyampom-hog-bear","subtitle":"Cryptid","details":"Northern California lumber lore tells of a bear of the Hyampom country, said to have a single tusk and an infamous appetite for hogs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fearsome%20Creatures%20of%20the%20Lumberwoods%2C%20with%20a%20Few%20Desert%20and%20Mountain%20Beasts%20%28page%2052%20crop%29.jpg?width=1024"},{"name":"Central American Whintosser","rarity":"uncommon","id":"central-american-whintosser","subtitle":"Cryptid","details":"Lumber lore tells of the Central American whintosser, a beast said to travel by forever turning its head as it walks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fearsome%20Creatures%20of%20the%20Lumberwoods%2C%20with%20a%20Few%20Desert%20and%20Mountain%20Beasts%20%28page%2046%20crop%29.jpg?width=1024"}]});
